// Coverage report for the feature sweep: what the guide promises, and which of it any card test or live check names.
// Writes tests/coverage.md (a generated file: run this after adding checks, never edit it by hand).
//
//   node scripts/stress/coverage.mjs [--out tests/coverage.md]
//
// A row of docs/guide/feature-index.md carries a task id (T-123, SESS-002, BROW-008 ...). A test file "covers" an id
// when the id appears in it: src/**/__cards__/*.test.ts (a unit/component card) or scripts/prove/live-*.mjs (a live
// check). Rows marked "internal" or "Removed" are counted apart, not as user-facing coverage.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";

export const ROOT = fileURLToPath(new URL("../../", import.meta.url)).replace(/[\\/]+$/, "");

const walk = (dir) =>
  readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const p = join(dir, e.name);
    return e.isDirectory() ? walk(p) : [p];
  });

/** Task ids the guide's rows name, with the area they sit in (its last heading). */
export function guideRows(indexFile = join(ROOT, "docs", "guide", "feature-index.md")) {
  const text = readFileSync(indexFile, "utf8");
  const rows = [];
  let area = "(no heading)";
  for (const line of text.split(/\r?\n/)) {
    const heading = /^#{1,4}\s+(.+)$/.exec(line);
    if (heading) area = heading[1].trim();
    if (!line.startsWith("|") || /^\|\s*-+/.test(line) || /^\|\s*(id|task|feature)\b/i.test(line)) continue;
    const cells = line.split("|").map((c) => c.trim());
    const ids = [...line.matchAll(/\b(?:T-\d+[a-z]?|[A-Z]{2,}-\d+[a-z]?)\b/g)].map((m) => m[0]);
    if (ids.length === 0) continue;
    const internal = cells.some((c) => /^internal$/i.test(c));
    const removed = /\bremoved\b/i.test(line);
    rows.push({ area, ids: [...new Set(ids)], internal, removed, text: cells[2] ?? cells[1] ?? "" });
  }
  return rows;
}

/** Ids each test file names. */
export function testIds(files) {
  const byId = new Map();
  for (const file of files) {
    const text = readFileSync(file, "utf8");
    for (const m of new Set([...text.matchAll(/\b(?:T-\d+[a-z]?|[A-Z]{2,}-\d+[a-z]?)\b/g)].map((x) => x[0]))) {
      if (!byId.has(m)) byId.set(m, []);
      byId.get(m).push(relative(ROOT, file).replace(/\\/g, "/"));
    }
  }
  return byId;
}

export function cardFiles() {
  return walk(join(ROOT, "src")).filter((f) => /[\\/]__cards__[\\/].*\.test\.tsx?$/.test(f));
}

export function liveFiles() {
  return walk(join(ROOT, "scripts", "prove")).filter((f) => /[\\/]live-.*\.mjs$/.test(f) && !/common|views-dom/.test(f));
}

/** Every test file that can name a task id: unit tests, card tests, the live checks, the stress and smoke scripts. */
export function anyTestFiles() {
  return [
    ...walk(join(ROOT, "src")).filter((f) => /\.test\.(ts|tsx)$/.test(f)),
    ...walk(join(ROOT, "scripts")).filter((f) => /\.(test\.)?mjs$/.test(f)),
  ];
}

/** The report as markdown. */
export function report() {
  const rows = guideRows();
  const tasks = [...new Set(rows.filter((r) => !r.internal && !r.removed).map((r) => r.ids[0]))];
  const named = testIds(anyTestFiles());
  const cards = [...new Set(cardFiles().map((f) => /([A-Z][A-Z0-9]+-[0-9]+)[^\/]*.test.tsx?$/.exec(f.split(/[\/]/).pop())?.[1]).filter(Boolean))];
  const liveIds = [...liveIdsOf()];
  const pct = (n, d) => (d === 0 ? "0.0%" : `${((100 * n) / d).toFixed(1)}%`);
  const tasksNamed = tasks.filter((t) => named.has(t));
  const cardsWithLive = cards.filter((c) => liveIds.includes(c));
  const liveOnly = liveIds.filter((c) => !cards.includes(c));

  const byArea = new Map();
  for (const r of rows) {
    if (r.internal || r.removed) continue;
    const a = byArea.get(r.area) ?? { tasks: new Set(), covered: new Set() };
    for (const id of r.ids) {
      a.tasks.add(id);
      if (named.has(id)) a.covered.add(id);
    }
    byArea.set(r.area, a);
  }

  return [
    "# Test coverage (generated)",
    "",
    "Generated by `node scripts/stress/coverage.mjs`. Re-run it after adding a check; never edit this file.",
    "",
    "Two different id namespaces exist, so there are two counts:",
    "",
    "1. **Guide tasks** (`T-123`, the `Task` column of `docs/guide/feature-index.md`): does any test file name it?",
    "2. **Feature-card areas** (`VIEW-021`, the name of a `src/**/__cards__/*.test.ts` file): does a live check exist for it?",
    "",
    "## 1. Guide tasks named by a test",
    "",
    `- User-facing tasks: **${tasks.length}**`,
    `- Named by at least one test file: **${tasksNamed.length}** (${pct(tasksNamed.length, tasks.length)})`,
    `- Named by nothing: **${tasks.length - tasksNamed.length}**`,
    "",
    "| Area | tasks | named by a test |",
    "|---|---:|---:|",
    ...[...byArea.entries()].map(([a, v]) => `| ${a} | ${v.tasks.size} | ${v.covered.size} |`),
    "",
    "## 2. Feature-card areas with a live check",
    "",
    `- Card areas: **${cards.length}**`,
    `- With a live check (same id in a scripts/prove/live-*.mjs name or text): **${cardsWithLive.length}** (${pct(cardsWithLive.length, cards.length)})`,
    `- Live checks for an id with no card test: **${liveOnly.length}**`,
    "",
    `With a live check: ${cardsWithLive.sort().join(", ") || "(none)"}`,
    "",
    `Live check without a card test: ${liveOnly.sort().join(", ") || "(none)"}`,
    "",
    "## Guide tasks named by no test",
    "",
    tasks.filter((t) => !named.has(t)).sort().join(", "),
    "",
  ].join("\n");
}

/** Every id a live check carries, from its file name and its text. */
export function liveIdsOf() {
  const ids = new Set();
  for (const file of liveFiles()) {
    const base = file.replace(/[\/]/g, "/").split("/").pop();
    for (const m of base.matchAll(/([A-Z]{2,}-\d+[a-z]?)/g)) ids.add(m[1]);
    const text = readFileSync(file, "utf8");
    for (const m of text.matchAll(/^\/\/.*([A-Z]{2,}-\d+[a-z]?)/gm)) ids.add(m[1]);
  }
  return ids;
}

if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1].replace(/\\/g, "/")}`).href) {
  const i = process.argv.indexOf("--out");
  const out = i >= 0 && process.argv[i + 1] ? process.argv[i + 1] : join(ROOT, "tests", "coverage.md");
  const text = report();
  writeFileSync(out, text);
  const totals = text.split("\n").filter((l) => /^-( Guide rows| Distinct| Covered)/.test(l));
  console.log(totals.join("\n"));
  console.log(`coverage: wrote ${out}`);
}
